function sortedArrayToBST(nums: number[]): TreeNode | null {
  // Строит сбалансированное BST из отрезка nums[l..r]
  const build = (l: number, r: number): TreeNode | null => {
    // Пустой отрезок — пустое поддерево
    if (l > r) {
      return null;
    }

    // Середина отрезка становится корнем:
    // слева от неё — меньшие числа, справа — большие
    const mid = Math.floor((l + r) / 2);
    const node = new TreeNode(nums[mid]);

    // Половины отличаются по размеру не более чем на 1,
    // поэтому поддеревья получаются сбалансированными
    node.left = build(l, mid - 1);
    node.right = build(mid + 1, r);

    return node;
  };

  return build(0, nums.length - 1);
}

// Время: O(n) — каждый элемент становится узлом ровно один раз
// Память: O(log n) — глубина рекурсии (не считая самого дерева)
